package com.dvopenlabs.freedom.companions;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.*;
import org.json.*;

/** Explicit foreground refresh, private credentials and local image export. Never contacts a server on open. */
public final class PhotoSourcesActivity extends PanelActivity {
    android.content.SharedPreferences prefs(){return getSharedPreferences("photo-sources",0);}
    File folder(){File f=new File(getCacheDir(),"photo-sources");f.mkdirs();return f;}
    @Override void home(){page("Personal photo sources","Choose your own Immich album or WebDAV folder. No refresh runs in the background. Preview and import a cached photo in Wallpaper Studio; your active wallpaper stays saved.",false);button("Connect or change source",this::configure);button("Refresh selected source now",this::refresh);File[] files=folder().listFiles(f->f.getName().matches("[a-f0-9]{64}\\.jpg"));if(files==null||files.length==0)page.addView(text("No cached photos. Connect a source, then refresh it explicitly.",18));else{Arrays.sort(files,Comparator.comparing(File::getName));int n=0;for(File f:files){if(n++>=12)break;LinearLayout row=new LinearLayout(this);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inSampleSize=4;image.setImageBitmap(BitmapFactory.decodeFile(f.getPath(),o));row.addView(image,new LinearLayout.LayoutParams(dp(160),dp(90)));page.addView(row);button("Preview photo "+n+" in Wallpaper Studio",()->{setResult(RESULT_OK,new Intent().setData(Uri.parse("content://com.dvopenlabs.freedom.companions.snapshot/photo/"+f.getName().replace(".jpg",""))));finish();});}}button("Forget credentials and photos",()->{prefs().edit().clear().apply();clearPhotos();home();});}
    void clearPhotos(){File[] files=folder().listFiles();if(files!=null)for(File file:files)if(file.getName().matches("[a-f0-9]{64}\\.jpg"))file.delete();}
    void configure(){var p=prefs();page("Connect your photos","Credentials stay in this companion. HTTPS verifies certificates. Local HTTP is unencrypted: use it only for a trusted server. Nothing is fetched until you press Refresh. Only one selected album/folder is requested, up to twelve photos.",true);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Immich album","WebDAV folder"}));type.setSelection(p.getString("type","immich").equals("dav")?1:0);page.addView(type);EditText address=field("Server URL / WebDAV folder URL",p.getString("url",""),false),album=field("Immich album ID (UUID)",p.getString("album",""),false),user=field("WebDAV username (leave empty for Immich)",p.getString("user",""),false),secret=field("Immich API key / WebDAV password",p.getString("secret",""),true);button("Save source",()->{try{String url=Network.url(address.getText().toString().trim(),true).toString();if(type.getSelectedItemPosition()==0&&!PhotoSourcePolicy.album(album.getText().toString().trim()))throw new IllegalArgumentException();String key=secret.getText().toString();if(key.isEmpty()||key.length()>4096||key.contains("\r")||key.contains("\n"))throw new IllegalArgumentException();clearPhotos();p.edit().putString("type",type.getSelectedItemPosition()==0?"immich":"dav").putString("url",url).putString("album",album.getText().toString().trim()).putString("user",user.getText().toString()).putString("secret",key).apply();home();}catch(Exception bad){Toast.makeText(this,"Check the address, credentials and album ID",Toast.LENGTH_LONG).show();}});button("Cancel",this::home);}
    void refresh(){var p=prefs();if(p.getString("url","").isEmpty()){configure();return;}page("Refreshing photos","Only the source you configured is contacted. Downloads stop when you leave this panel.",true);TextView status=text("Loading up to twelve photos…",18);page.addView(status);button("Back",this::home);String type=p.getString("type","immich"),url=p.getString("url",""),secret=p.getString("secret",""),album=p.getString("album",""),user=p.getString("user","");int token=generation;
        load(()->{
            Map<String,String> headers=new HashMap<>();List<String> photos=new ArrayList<>();if(type.equals("immich")){headers.put("x-api-key",secret);String base=url.replaceAll("/+$","");JSONObject data=new JSONObject(new String(Network.requestWith("GET",base+"/api/albums/"+album,headers,null,true,1024*1024),StandardCharsets.UTF_8));JSONArray assets=data.optJSONArray("assets");for(int i=0;assets!=null&&i<assets.length()&&photos.size()<12;i++){JSONObject asset=assets.optJSONObject(i);if(asset!=null&&"IMAGE".equals(asset.optString("type"))&&PhotoSourcePolicy.album(asset.optString("id")))photos.add(base+"/api/assets/"+asset.getString("id")+"/thumbnail?size=preview");}}
            else{headers.put("Authorization",okhttp3.Credentials.basic(user,secret));headers.put("Depth","1");String base=url.endsWith("/")?url:url+"/";byte[] data=Network.requestWith("PROPFIND",base,headers,"<?xml version=\"1.0\"?><d:propfind xmlns:d=\"DAV:\"><d:prop><d:resourcetype/></d:prop></d:propfind>",true,1024*1024);DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);NodeList nodes=f.newDocumentBuilder().parse(new ByteArrayInputStream(data)).getElementsByTagNameNS("DAV:","href");for(int i=0;i<nodes.getLength()&&i<128&&photos.size()<12;i++)try{photos.add(PhotoSourcePolicy.child(base,nodes.item(i).getTextContent()));}catch(IllegalArgumentException ignored){}}
            int count=0;for(String photo:photos){if(Thread.currentThread().isInterrupted()||!visible||generation!=token)throw new IOException();byte[] bytes=Network.requestWith("GET",photo,headers,null,true,4*1024*1024);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<=0||o.outHeight<=0||(long)o.outWidth*o.outHeight>32_000_000)continue;o.inSampleSize=1;while((long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>1920L*1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(image==null)continue;if(Thread.currentThread().isInterrupted()||!visible||generation!=token){image.recycle();throw new IOException();}File target=new File(folder(),DiscoverStore.hash(photo)+".jpg");try(OutputStream out=new FileOutputStream(target)){image.compress(Bitmap.CompressFormat.JPEG,86,out);}finally{image.recycle();}count++;}
            File[] files=folder().listFiles();if(files!=null){Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long kept=0;for(int i=0;i<files.length;i++){if(i>=12||kept+files[i].length()>16L*1024*1024)files[i].delete();else kept+=files[i].length();}}return count;
        },count->{status.setText(count+" photos cached. No wallpaper was selected.");button("View cached photos",this::home);},bad->status.setText("Refresh unavailable. Check your server version, album/folder access and credentials. Existing cached photos are kept."));
    }
    @Override public void onBackPressed(){finish();}
}
